&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What you will bring&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are looking for applicants with the following traits and skills:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Academic background: &lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Master’s or PhD in physics, maths, engineering, or other related disciplines&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Business mindset:&lt;/span&gt;&lt;/strong&gt; &lt;span data-contrast=&quot;auto&quot;&gt;Ap&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;preciat&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;io&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;n of&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; h&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;ow te&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;ch is&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; commerc&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;ialis&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;ed whi&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;ch may&lt;/span&gt; &lt;span data-contrast=&quot;auto&quot;&gt;be d&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;emonstra&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;ted &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;throu&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;gh&lt;/span&gt; &lt;span data-contrast=&quot;auto&quot;&gt;Experience &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;e&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;xperience &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;in entrepreneurship (e.g. student business plan competitions, internships, start-ups), business or economics modules as part of an integrated Master’s&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;, &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;co&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;mplet&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;in&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;g&lt;/span&gt; &lt;span data-contrast=&quot;auto&quot;&gt;evenin&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;g&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; clas&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;ses&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; or a Master’s degree with a business/strategy focus following a science or technology degree&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Analytical and creative thinking:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Ability to turn complex technical concepts into actionable strategies&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Curiosity and adaptability:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; A passion for learning and applying insights across multiple sectors&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
